mapper.select:
-- 관리자에게 snapshot 원문을 직렬화하지 않고 response projection만 반환한다.
SELECT ,NULL::text AS input_snapshot_json  WHERE v.policy_id=#{policyId}
ORDER BY v.created_at DESC,v.id DESC LIMIT #{size} OFFSET #{offset}

mapper.insert:
-- 같은 live run에서 서버가 실행한 단계만 기록한다. 늦은 owner는 기록할 수 없다.
INSERT INTO announcement_attachment_policy_validation_steps(run_id,step_code,status_code,evidence_json,evidence_hash)
SELECT id,#{stepCode},#{statusCode},CAST(#{evidenceJson} AS jsonb),#{evidenceHash}
FROM announcement_attachment_policy_validation_runs WHERE id=#{runId} AND lease_token=#{leaseToken}
    AND run_status_code='RUNNING' AND lease_expires_at>clock_timestamp()
